@description('GDK Version')
@allowed([ 'June_2022_Update_1', 'March_2022_Update_1', 'October_2021_Update_5', 'June_2021_Update_9' ])
param gdkVersion string = 'June_2021_Update_9'

@description('Incredibuild License Key')
@secure()
param ibLicenseKey string = ''

@description('Remote Access technology')
@allowed([ 'RDP', 'Teradici', 'Parsec' ])
param remoteAccessTechnology string = 'RDP'

@description('Teradici Registration Key')
@secure()
param teradiciRegKey string = ''

@description('Parsec Team ID')
param parsec_teamId string = ''

@description('Parsec Team Key')
@secure()
param parsec_teamKey string = ''

@description('Parsec Hostname')
param parsec_host string = ''

@description('Parsec User Email')
param parsec_userEmail string = ''

@description('Parsec Is Guest Access')
param parsec_isGuestAccess bool = false

@description('Number of data disks')
param numDataDisks int = 0

@description('Disk Performance Tier')
param dataDiskSize int = 1024

@description('File Share Storage Account name')
param fileShareStorageAccount string = ''

@description('File Share Storage Account key')
@secure()
param fileShareStorageAccountKey string = ''

@description('File Share name')
param fileShareName string = ''

@description('Perforce Port address')
param p4Port string = ''

@description('Perforce User')
param p4Username string = ''

@description('Perforce User password')
@secure()
param p4Password string = ''

@description('Perforce Client Workspace')
param p4Workspace string = ''

@description('Perforce Stream')
param p4Stream string = ''

@description('Perforce Depot Client View mappings')
param p4ClientViews string = ''

@description('Virtual Network name')
param vnetName string = 'gamedev-vnet'

@description('Address prefix of the virtual network')
param vnetARPrefixes array = [ '10.0.0.0/26' ]

@description('Virtual network is new or existing')
param vnetNewOrExisting string = 'new'

@description('Resource Group of the Virtual network')
param vnetRGName string = resourceGroup().name

@description('VM Subnet name')
param subNetName string = 'gamedev-vnet-subnet1'

@description('Subnet prefix of the virtual network')
param subNetARPrefix string = '10.0.0.0/28'

@description('Unique public ip address name')
param publicIpName string = 'GameDevVM-IP'

@description('Unique DNS Public IP attached the VM')
param publicIpDns string = 'gamedevvm${uniqueString(resourceGroup().id)}'

@description('Public IP Allocoation Method')
param publicIpAllocationMethod string = 'Dynamic'

@description('SKU number')
@allowed([ 'Basic', 'Standard' ])
param publicIpSku string = 'Basic'

@description('Public IP New or Existing or None?')
@allowed([ 'new', 'existing', 'none' ])
param publicIpNewOrExisting string = 'new'

@description('Resource Group of the Public IP Address')
param publicIpRGName string = resourceGroup().name

@description('Select Image Deployment for debugging only')
@allowed([ 'development', 'production' ])
param environment string = 'production'

@description('Tags by resource.')
param outTagsByResource object = {}

@description('Enable or disable Unreal Pixel Streaming port.')
param unrealPixelStreamingEnabled bool = false

@description('Enable or disable the use of a Managed Identity for the VM.')
param enableManagedIdentity bool = false

@description('Enable or disable AAD-based login.')
param enableAAD bool = false

@description('Specifies the OS patching behavior.')
@allowed([ 'AutomaticByOS', 'AutomaticByPlatform', 'Manual' ])
param windowsUpdateOption string = 'AutomaticByOS'

module gameDevVM 'br/public:azure-gaming/game-dev-vm:1.0.2' = {
  name: 'gameDevVM-${deployment().name}'
  params: {
    location: location
    vmSize: vmSize
    useVmToSysprepCustomImage: useVmToSysprepCustomImage
    vmName: vmName
    adminName: adminName
    adminPass: adminPass
    osType: osType
    gameEngine: gameEngine
    gdkVersion: gdkVersion
    ibLicenseKey: ibLicenseKey
    remoteAccessTechnology: remoteAccessTechnology
    teradiciRegKey: teradiciRegKey
    parsec_teamId: parsec_teamId
    parsec_teamKey: parsec_teamKey
    parsec_host: parsec_host
    parsec_userEmail: parsec_userEmail
    parsec_isGuestAccess: parsec_isGuestAccess
    numDataDisks: numDataDisks
    dataDiskSize: dataDiskSize
    fileShareStorageAccount: fileShareStorageAccount
    fileShareStorageAccountKey: fileShareStorageAccountKey
    fileShareName: fileShareName
    p4Port: p4Port
    p4Username: p4Username
    p4Password: p4Password
    p4Workspace: p4Workspace
    p4Stream: p4Stream
    p4ClientViews: p4ClientViews
    vnetName: vnetName
    vnetARPrefixes: vnetARPrefixes
    vnetNewOrExisting: vnetNewOrExisting
    vnetRGName: vnetRGName
    subNetName: subNetName
    subNetARPrefix: subNetARPrefix
    publicIpName: publicIpName
    publicIpDns: publicIpDns
    publicIpAllocationMethod: publicIpAllocationMethod
    publicIpSku: publicIpSku
    publicIpNewOrExisting: publicIpNewOrExisting
    publicIpRGName: publicIpRGName
    environment: environment
    outTagsByResource: outTagsByResource
    unrealPixelStreamingEnabled: unrealPixelStreamingEnabled
    enableManagedIdentity: enableManagedIdentity
    enableAAD: enableAAD
    windowsUpdateOption: windowsUpdateOption
  }
}

@description('Deployment Location')
param location string = resourceGroup().location

@description('Name of VMSS Cluster')
param vmssName string

@description('GameDev Sku')
param vmssSku string = 'Standard_D4ds_v4'

@description('GameDev Image Publisher')
@allowed([
  'microsoftcorporation1602274591143'
  'azure-gaming'
])
param vmssImgPublisher string = 'microsoftcorporation1602274591143'

@description('GameDev Image Product Id')
@allowed([
  'game-dev-vm'
])
param vmssImgProduct string = 'game-dev-vm'

@description('GameDev Image Sku')
@allowed([
  'win10_no_engine_1_0'
  'ws2019_no_engine_1_0'
  'win10_unreal_4_27_2'
  'ws2019_unreal_4_27_2'
  'win10_unreal_5_0_1'
  'ws2019_unreal_5_0_1'
])
param vmssImgSku string = 'win10_unreal_4_27_2'

@description('GameDev Image Product Id')
param vmssImgVersion string = 'latest'

@description('GameDev Disk Type')
param vmssOsDiskType string = 'Premium_LRS'

@description('VMSS Instance Count')
@maxValue(100)
@minValue(1)
param vmssInstanceCount int = 1

@description('Administrator Login for access')
param administratorLogin string

@description('Administrator Password for access')
@secure()
param passwordAdministratorLogin string

@description('File Share Storage Account name')
param fileShareStorageAccount string = ''

@description('File Share Storage Account key')
@secure()
param fileShareStorageAccountKey string = ''

@description('File Share name')
param fileShareName string = ''

@description('Perforce Port address')
param p4Port string = ''

@description('Perforce User')
param p4Username string = ''

@description('Perforce User password')
@secure()
param p4Password string = ''

@description('Perforce Client Workspace')
param p4Workspace string = ''

@description('Perforce Stream')
param p4Stream string = ''

@description('Perforce Depot Client View mappings')
param p4ClientViews string = ''

@description('Incredibuild License Key')
@secure()
param ibLicenseKey string = ''

@description('GDK Version')
param gdkVersion string = 'June_2021_Update_4'

@description('Use VM to sysprep an image from')
param useVmToSysprepCustomImage bool = false

@description('Remote Access technology')
@allowed([
  'RDP'
  'Teradici'
  'Parsec'
])
param remoteAccessTechnology string = 'RDP'

@description('Teradici Registration Key')
@secure()
param teradiciRegKey string = ''

@description('Parsec Team ID')
param parsecTeamId string = ''

@description('Parsec Team Key')
@secure()
param parsecTeamKey string = ''

@description('Parsec Hostname')
param parsecHost string = ''

@description('Parsec User Email')
param parsecUserEmail string = ''

@description('Parsec Is Guest Access')
param parsecIsGuestAccess bool = false

@description('Virtual Network Resource Name')
param vnetName string = 'vnet-${vmssName}'

@description('Virtual Network Subnet Name')
param subnetName string = 'subnet${vmssName}'

@description('Virtual Network Security Group Name')
param networkSecurityGroupName string = 'nsg-${vmssName}'

@description('Virtual Network Address Prefix')
param vnetAddressPrefix string = '172.17.72.0/24' //Change as needed

@description('Virtual Network Subnet Address Prefix')
param subnetAddressPrefix string = '172.17.72.0/25' // 172.17.72.[0-128] is part of this subnet

var customData = format('''
fileShareStorageAccount={0}
fileShareStorageAccountKey={1}
fileShareName={2}
p4Port={3}
p4Username={4}
p4Password={5}
p4Workspace={6}
p4Stream={7}
p4ClientViews={8}
ibLicenseKey={9}
gdkVersion={10}
useVmToSysprepCustomImage={11}
remoteAccessTechnology={12}
teradiciRegKey={13}
parsecTeamId={14}
parsecTeamKey={15}
parsecHost={16}
parsecUserEmail={17}
parsecIsGuestAccess={18}
deployedFromSolutionTemplate={19}
''', fileShareStorageAccount, fileShareStorageAccountKey, fileShareName, p4Port, p4Username, p4Password, p4Workspace, p4Stream, p4ClientViews, ibLicenseKey, gdkVersion, useVmToSysprepCustomImage, remoteAccessTechnology, teradiciRegKey, parsecTeamId, parsecTeamKey, parsecHost, parsecUserEmail, parsecIsGuestAccess, false)


module vnet './nestedtemplates/virtualNetworks.bicep'  = {
  name:                       vnetName
  params: {
    location:                 location
    vnetName:                 vnetName
    subnetName:               subnetName
    networkSecurityGroupName: networkSecurityGroupName
    vnetAddressPrefix:        vnetAddressPrefix
    subnetAddressPrefix:      subnetAddressPrefix
  }
}

resource vmss 'Microsoft.Compute/virtualMachineScaleSets@2021-04-01' = {
  name: vmssName
  location: location
  sku: {
    name:     vmssSku
    tier:     'Standard'
    capacity: vmssInstanceCount
  }
  plan: {
    name:      vmssImgSku
    publisher: vmssImgPublisher
    product:   vmssImgProduct
  }  
  properties: {
    singlePlacementGroup: false
    upgradePolicy: {
      mode: 'Manual'
    }
    virtualMachineProfile: {
      storageProfile: {
        osDisk: {
          createOption: 'FromImage'
          caching: 'ReadWrite'
          managedDisk: {
            storageAccountType: vmssOsDiskType
          }
        }
        imageReference: {
          publisher: vmssImgPublisher
          offer:     vmssImgProduct
          sku:       vmssImgSku
          version:   vmssImgVersion
	}
      }
      networkProfile: {
        networkInterfaceConfigurations: [
          {
            name: '${vmssName}Nic'
            properties: {
              primary: true
              ipConfigurations: [
                {
                  name: '${vmssName}IpConfig'
                  properties: {
                    subnet: {
                      id: vnet.outputs.subnetId
                    }
                  }
                }
              ]
              networkSecurityGroup: {
                id: vnet.outputs.nsgID
              }
            }
          }
        ]
      }
      osProfile: {
        computerNamePrefix: vmssName
        adminUsername:      administratorLogin
        adminPassword:      passwordAdministratorLogin
	customData:         base64(customData)
	windowsConfiguration: {
          provisionVMAgent: true
        }	
      }
      priority: 'Regular'
    }
    overprovision: false
  }
}

output id   string = vmss.id
output name string = vmss.name

@description('Location for all resources. The default is the Resource Group location.')
param location string = resourceGroup().location

@description('Name of the Virtual Network Resource Group.')
param virtualNetworkResourceGroupName string

@description('Name of the Virtual Network, should be in the above Location.')
param virtualNetworkName string

@description('Name of the Subnet in the Virtual Network.')
param subnet1Name string

@description('Name for the Network Security Group that the template will create. Note that a pre-existing Network Security Group with the same name will be replaced.')
param networkSecurityGroupName string

@description('Provide an address range using CIDR notation (e.g. 10.1.0.0/24), or an IP address (e.g. 192.168.99.21) for Management access via ssh (port 22/TCP). You can also provide a comma-separated list of IP addresses and/or address ranges (a valid comma-separated list is 10.1.0.4,10.2.1.0/24). To allow access from any IP you can use 0.0.0.0/0.')
param MgmtSourceAddressOrRange string

@description('The name of the vSensor.')
param vsensorName string

@description('Number of vSensors to be deployed, max is 4.')
@minValue(1)
@maxValue(4)
param numberOfVsensors int = 1

@description('The vSensor disk size in GB between 30 and 1024. Check the Darktrace customer portal for more information.')
@minValue(30)
@maxValue(1024)
param diskSize int = 30

@description('The VM size. Check the Darktrace customer portal for more information about the vSensor Virtual Hardware requirements.')
param virtualMachineSize string = 'Standard_D2s_v3'

@description('Username to be created when the vSensor is spun up. Note that password authentication over ssh for newly created VMs is disabled.')
param adminUsername string

@description('Public key for the adminUsername user to ssh the vSensor.')
param adminPublicKey string = ''

@description('The FQDN or the IP of the Darktrace master instance (virtual/physical).')
param applianceHostName string

@description('Darktrace master instance connection port.')
@minValue(1)
@maxValue(65535)
param appliancePort int = 443

@description('Darktrace Update Key needed to install the vSensor package. Contact your Darktrace representative for more information.')
@secure()
param updateKey string

@description('The push token that vSensor will use to connect and register on the Darktrace master instance. Should be generated on the Darktrace master instance.')
@secure()
param pushToken string

@description('TThe osSensor HMAC Token.')
@secure()
param osSensorHMACToken string

var nsgSourceAddressPrefix = split(varMgmtSourceAddressOrRange, ',')
var varMgmtSourceAddressOrRange = replace(MgmtSourceAddressOrRange, ' ', '')

resource networkSecurityGroup 'Microsoft.Network/networkSecurityGroups@2025-03-01' = {
  name: networkSecurityGroupName
  location: location
  properties: {
    securityRules: [
      {
        name: 'AllowMgmtInPorts22'
        properties: {
          description: 'Allow Inbound traffic to TCP ports 22 from customer selected IPs/Ranges.'
          direction: 'Inbound'
          priority: 1001
          access: 'Allow'
          protocol: 'TCP'
          sourcePortRange: '*'
          destinationPortRanges: [
            '22'
          ]
          sourceAddressPrefixes: nsgSourceAddressPrefix
          destinationAddressPrefix: '*'
        }
      }
      {
        name: 'AllowVnetInPorts80_443'
        properties: {
          description: 'Allow Inbound traffic to TCP ports 80 and 443 from all VMs in the Vnet.'
          direction: 'Inbound'
          priority: 1011
          access: 'Allow'
          protocol: 'TCP'
          sourcePortRange: '*'
          destinationPortRanges: [
            '80'
            '443'
          ]
          sourceAddressPrefix: 'VirtualNetwork'
          destinationAddressPrefix: 'VirtualNetwork'
        }
      }
      {
        name: 'DenyAllIn'
        properties: {
          description: 'Deny all Inbound traffic.'
          direction: 'Inbound'
          priority: 1021
          access: 'Deny'
          protocol: '*'
          sourcePortRange: '*'
          destinationPortRange: '*'
          sourceAddressPrefix: '*'
          destinationAddressPrefix: '*'
        }
      }
    ]
  }
}

resource nic 'Microsoft.Network/networkInterfaces@2025-03-01' = [for i in range(0, numberOfVsensors): {
  name: '${vsensorName}-${i+1}-nic'
  location: location
  properties: {
    ipConfigurations: [
      {
        name: 'ipconfig1'
        properties: {
          subnet: {
            id: resourceId(virtualNetworkResourceGroupName, 'Microsoft.Network/virtualNetworks/subnets', virtualNetworkName, subnet1Name)
          }
          privateIPAllocationMethod: 'Dynamic'
        }
      }
    ]
    enableAcceleratedNetworking: true
    networkSecurityGroup: {
      id: networkSecurityGroup.id
    }
  }
}]

resource vm 'Microsoft.Compute/virtualMachines@2025-04-01' = [for i in range(0, numberOfVsensors): {
  name: '${vsensorName}-${i+1}'
  location: location
  properties: {
    hardwareProfile: {
      vmSize: virtualMachineSize
    }
    storageProfile: {
      osDisk: {
        createOption: 'fromImage'
        diskSizeGB: diskSize
        managedDisk: {
          storageAccountType: 'StandardSSD_LRS'
        }
        deleteOption: 'delete'
      }
      imageReference: {
        publisher: 'Canonical'
        offer: 'ubuntu-24_04-lts'
        sku: 'server'
        version: 'latest'
      }
    }
    networkProfile: {
      networkInterfaces: [
        {
          id: nic[i].id
          properties: {
            deleteOption: 'delete'
          }
        }
      ]
    }
    osProfile: {
      computerName: vsensorName
      adminUsername: adminUsername
      linuxConfiguration: {
        disablePasswordAuthentication: true
        ssh: {
          publicKeys: [
            {
              path: '/home/${adminUsername}/.ssh/authorized_keys'
              keyData: adminPublicKey
            }
          ]
        }
        patchSettings: {
          patchMode: 'ImageDefault'
        }
      }
      customData: base64('#!/bin/bash
bash <(wget https://packages-cdn.darktrace.com/install -O -) --updateKey "${updateKey}"
 sleep 5
/usr/sbin/set_pushtoken.sh "${pushToken}" ${applianceHostName}:${appliancePort}
sleep 5
set_ossensor_hmac.sh "${osSensorHMACToken}"')
    }
    diagnosticsProfile: {
      bootDiagnostics: {
        enabled: true
      }
    }
  }
}]

output allowedManagementIPsAndRanges array = nsgSourceAddressPrefix

@description('Username for Administrator Account')
param adminUsername string

@description('The name of you Virtual Machine.')
param vmName string = 'vmName'

@description('Location for all resources.')
param location string = resourceGroup().location

@description('Choose between CPU or GPU processing')
@allowed([
  'CPU-4GB'
  'CPU-7GB'
  'CPU-8GB'
