@description('Username you want to use for the VM the template creates')
param adminUsername string

@description('Size of the VM')
param vmSize string = 'Standard_A2_v2'

@description('The DNS name (prefix) you want to use for the VM to map against its public IP')
param dnsNameForPublicIP string = uniqueString(resourceGroup().id)

@description('The SAS URL connection string for the storage account blog where your Application Gateway Access Logs are stored')
param appGwAccessLogsBlobSasUri string

@description('A regex to use to filter the Application Gateway Access Logs to a specific subset. For example, if you have multiple application gateways publishing logs to the same storage account blob, and you only want GoAccess to surface traffic stats for say one of the Application Gateways, you can provide a regex for this field to filter to just that instance.')
param filterRegexForAppGwAccessLogs string = '.*'

@description('Location for all resources.')
param location string = resourceGroup().location

@description('The base URI where artifacts required by this template are located including a trailing '/'')
param _artifactsLocation string = deployment().properties.templateLink.uri

@description('The sasToken required to access _artifactsLocation.  When the template is deployed using the accompanying scripts, a sasToken will be automatically generated. Use the defaultValue if the staging location is not secured.')
@secure()
param _artifactsLocationSasToken string = ''

@description('Type of authentication to use on the Virtual Machine. SSH key is recommended.')
@allowed([
  'sshPublicKey'
  'password'
])
param authenticationType string = 'sshPublicKey'

@description('SSH Key or password for the Virtual Machine. SSH key is recommended.')
@secure()
param adminPasswordOrKey string

var vmName = dnsNameForPublicIP
var nicName = '${dnsNameForPublicIP}_vmnic'
var addressPrefix = '10.0.0.0/16'
var subnetPrefix = '10.0.0.0/24'
var subnetName = 'DefaultSubnet'
var publicIPAddressName = '${dnsNameForPublicIP}_publicip'
var virtualNetworkName = '${dnsNameForPublicIP}_vnet'
var networkSecurityGroupName = '${dnsNameForPublicIP}_nsg'
var scriptFileUri = uri(_artifactsLocation, 'scripts/setup_vm.sh${_artifactsLocationSasToken}')
var appGatewayLogProcessorArtifactUri = uri(_artifactsLocation, 'scripts/AppGatewayLogProcessor.zip${_artifactsLocationSasToken}')
var appGwAccessLogsBlobSasUriVar = '"${appGwAccessLogsBlobSasUri}"'
var filterRegexForAppGwAccessLogsVar = '"|${filterRegexForAppGwAccessLogs}|"'
var linuxConfiguration = {
  disablePasswordAuthentication: true
  ssh: {
    publicKeys: [
      {
        path: '/home/${adminUsername}/.ssh/authorized_keys'
        keyData: adminPasswordOrKey
      }
    ]
  }
}

resource publicIPAddress 'Microsoft.Network/publicIPAddresses@2023-09-01' = {
  name: publicIPAddressName
  location: location
  properties: {
    publicIPAllocationMethod: 'Dynamic'
    dnsSettings: {
      domainNameLabel: dnsNameForPublicIP
    }
  }
}

resource networkSecurityGroup 'Microsoft.Network/networkSecurityGroups@2023-09-01' = {
  name: networkSecurityGroupName
  location: location
  properties: {
    securityRules: [
      {
        name: 'ssh'
        properties: {
          protocol: 'Tcp'
          sourcePortRange: '*'
          destinationPortRange: '22'
          sourceAddressPrefix: '*'
          destinationAddressPrefix: '*'
          access: 'Allow'
          priority: 132
          direction: 'Inbound'
        }
      }
      {
        name: 'http'
        properties: {
          protocol: 'Tcp'
          sourcePortRange: '*'
          destinationPortRange: '80'
          sourceAddressPrefix: '*'
          destinationAddressPrefix: '*'
          access: 'Allow'
          priority: 131
          direction: 'Inbound'
        }
      }
      {
        name: 'https'
        properties: {
          protocol: 'Tcp'
          sourcePortRange: '*'
          destinationPortRange: '443'
          sourceAddressPrefix: '*'
          destinationAddressPrefix: '*'
          access: 'Allow'
          priority: 130
          direction: 'Inbound'
        }
      }
      {
        name: 'GoAccessSocket'
        properties: {
          protocol: 'Tcp'
          sourcePortRange: '*'
          destinationPortRange: '8080'
          sourceAddressPrefix: '*'
          destinationAddressPrefix: '*'
          access: 'Allow'
          priority: 129
          direction: 'Inbound'
        }
      }
    ]
  }
}

resource virtualNetwork 'Microsoft.Network/virtualNetworks@2023-09-01' = {
  name: virtualNetworkName
  location: location
  properties: {
    addressSpace: {
      addressPrefixes: [
        addressPrefix
      ]
    }
    subnets: [
      {
        name: subnetName
        properties: {
          addressPrefix: subnetPrefix
        }
      }
    ]
  }
}

resource nic 'Microsoft.Network/networkInterfaces@2023-09-01' = {
  name: nicName
  location: location
  properties: {
    ipConfigurations: [
      {
        name: 'ipconfig1'
        properties: {
          privateIPAllocationMethod: 'Dynamic'
          publicIPAddress: {
            id: publicIPAddress.id
          }
          subnet: {
            id: resourceId('Microsoft.Network/virtualNetworks/subnets', virtualNetworkName, subnetName)
          }
        }
      }
    ]
    networkSecurityGroup: {
      id: networkSecurityGroup.id
    }
  }
  dependsOn: [
    virtualNetwork
  ]
}

resource vm 'Microsoft.Compute/virtualMachines@2023-09-01' = {
  name: vmName
  location: location
  properties: {
    hardwareProfile: {
      vmSize: vmSize
    }
    osProfile: {
      computerName: vmName
      adminUsername: adminUsername
      adminPassword: adminPasswordOrKey
      linuxConfiguration: ((authenticationType == 'password') ? null : linuxConfiguration)
    }
    storageProfile: {
      imageReference: {
        publisher: 'Canonical'
        offer: 'UbuntuServer'
        sku: '18.04-LTS'
        version: 'latest'
      }
      osDisk: {
        name: '${vmName}_osdisk'
        caching: 'ReadWrite'
        createOption: 'FromImage'
        managedDisk: {
          storageAccountType: 'StandardSSD_LRS'
        }
      }
      dataDisks: [
        {
          name: '${vmName}_datadisk1'
          diskSizeGB: 1023
          lun: 0
          createOption: 'Empty'
          managedDisk: {
            storageAccountType: 'StandardSSD_LRS'
          }
        }
      ]
    }
    networkProfile: {
      networkInterfaces: [
        {
          id: nic.id
        }
      ]
    }
  }
}

resource newUserScript 'Microsoft.Compute/virtualMachines/extensions@2023-09-01' = {
  parent: vm
  name: 'newuserscript'
  location: location
  properties: {
    publisher: 'Microsoft.Azure.Extensions'
    type: 'CustomScript'
    typeHandlerVersion: '2.0'
    autoUpgradeMinorVersion: true
    settings: {
      fileUris: [
        scriptFileUri
        appGatewayLogProcessorArtifactUri
      ]
      commandToExecute: 'sh setup_vm.sh ${appGwAccessLogsBlobSasUriVar} ${filterRegexForAppGwAccessLogsVar}'
    }
  }
}

output goAccessReportUrl string = '${publicIPAddress.properties.dnsSettings.fqdn}/report.html'
output sshCommand string = 'ssh ${adminUsername}@${publicIPAddress.properties.dnsSettings.fqdn}'

@description('Name of the Azure Storage account.')
param storageAccountName string = 'storage${uniqueString(resourceGroup().id)}'

@description('Sku on which to run the Azure Storage account.')
@allowed([
  'Standard_LRS'
  'Standard_GRS'
  'Standard_RAGRS'
  'Standard_ZRS'
  'Premium_LRS'
  'Premium_ZRS'
  'Standard_GZRS'
  'Standard_RAGZRS'
])
param storageAccountSku string = 'Standard_LRS'

@description('Indicates the type of storage account.')
@allowed([
  'Storage'
  'StorageV2'
  'BlobStorage'
  'FileStorage'
  'BlockBlobStorage'
])
param storageAccountKind string = 'StorageV2'

@description('Set the name of the container to create in the Storage account.')
param storageAccountContainerName string = 'my-container'

@description('Name of the Logic Apps API connection used to connect to the Azure Storage account.')
param storageConnectionName string = 'storageconnection${uniqueString(resourceGroup().id)}'

@description('Name of the Logic App.')
param logicAppName string = 'logicapp${uniqueString(resourceGroup().id)}'

@description('The polling interval used to check for items on the Storage account.')
param logicAppPollingIntervalInMinutes int = 30

@description('Location where resources reside.')
param location string = resourceGroup().location

@description('Azure Management URI')
param azureMgmtUri string = ''

resource storageConnection 'Microsoft.Web/connections@2016-06-01' = {
  name: storageConnectionName
  location: location
  properties: {
    api: {
      id: subscriptionResourceId('Microsoft.Web/locations/managedApis', location, 'azureblob')
    }
    parameterValues: {
      accountName: storageAccountName
      accessKey: storageAccount.listkeys().keys[0].value
    }
    testLinks: [
      {
        requestUri: uri(
          azureMgmtUri,
          'subscriptions/${subscription().subscriptionId}/resourceGroups/${resourceGroup().name}/providers/Microsoft.Web/connections/${storageConnectionName}/extensions/proxy/testconnection?api-version=2018-07-01-preview'
        )
        method: 'get'
      }
    ]
  }
}

resource storageAccount 'Microsoft.Storage/storageAccounts@2023-01-01' = {
  name: storageAccountName
  location: location
  sku: {
    name: storageAccountSku
  }
  kind: storageAccountKind
  properties: {
    accessTier: 'Hot'
    supportsHttpsTrafficOnly: true
    minimumTlsVersion: 'TLS1_2'
    allowBlobPublicAccess: false
  }
}

resource logicApp 'Microsoft.Logic/workflows@2019-05-01' = {
  name: logicAppName
  location: location
  properties: {
    definition: {
      '$schema': 'https://schema.management.azure.com/providers/Microsoft.Logic/schemas/2016-06-01/workflowdefinition.json#'
      contentVersion: '1.0.0.0'
      parameters: {
        '$connections': {
          defaultValue: {}
          type: 'Object'
        }
      }
      triggers: {
        'When_a_blob_is_added_or_modified_(properties_only)': {
          recurrence: {
            frequency: 'Minute'
            interval: logicAppPollingIntervalInMinutes
          }
          splitOn: '@triggerBody()'
          metadata: {
            JTJmbXktY29udGFpbmVy: '/${storageAccountContainerName}'
          }
          type: 'ApiConnection'
          inputs: {
            host: {
              connection: {
                name: '@parameters('$connections')['azureblob']['connectionId']'
              }
            }
            method: 'get'
            path: '/datasets/default/triggers/batch/onupdatedfile'
            queries: {
              folderId: 'JTJmbXktY29udGFpbmVy'
              maxFileCount: 10
            }
          }
        }
      }
      actions: {
        Process_blobs: {
          type: 'Scope'
        }
      }
    }
    parameters: {
      '$connections': {
        value: {
          azureblob: {
            connectionId: storageConnection.id
            connectionName: 'azureblob'
            id: subscriptionResourceId('Microsoft.Web/locations/managedApis', location, 'azureblob')
          }
        }
      }
    }
    state: 'Enabled'
  }
}

output logicAppName string = logicApp.name
output logicAppId string = logicApp.id
output location string = logicApp.location
output resourceGroupName string = resourceGroup().name

@description('Specify the name of your Automation Account')
param automationAccountName string

@description('Default modules URI')
