param automationRegion string

@description('URI to artifacts location')
param _artifactsLocation string = deployment().properties.templateLink.uri

@description('The sasToken required to access _artifactsLocation.  When the template is deployed using the accompanying scripts, a sasToken will be automatically generated')
@secure()
param _artifactsLocationSasToken string = ''

var assets = {
  aaVariables: {
    AzureSubscriptionId: {
      name: 'AzureSubscriptionId'
      description: 'Azure subscription Id'
    }
  }
}
var asrScripts = {
  runbooks: [
    {
      name: 'ASR-AddPublicIp'
      url: uri(_artifactsLocation, 'scripts/ASR-AddPublicIp.ps1${_artifactsLocationSasToken}')
      version: '1.0.0.0'
      type: 'PowerShell'
      description: 'ASR Runbook to enable public IP on every VM in a Recovery Plan'
    }
    {
      name: 'ASR-SQL-FailoverAG'
      url: uri(_artifactsLocation, 'scripts/ASR-SQL-FailoverAG.ps1${_artifactsLocationSasToken}')
      version: '1.0.0.0'
      type: 'PowerShellWorkflow'
      description: 'ASR Runbook to handle SQL Always On failover'
    }
    {
      name: 'ASR-AddSingleNSGPublicIp'
      url: uri(_artifactsLocation, 'scripts/ASR-AddSingleNSGPublicIp.ps1${_artifactsLocationSasToken}')
      version: '1.0.0.0'
      type: 'PowerShell'
      description: 'ASR Runbook to enable NSG and Public IP on every VM in a Recovery Plan'
    }
    {
      name: 'ASR-AddSingleLoadBalancer'
      url: uri(_artifactsLocation, 'scripts/ASR-AddSingleLoadBalancer.ps1${_artifactsLocationSasToken}')
      version: '1.0.0.0'
      type: 'PowerShell'
      description: 'ASR Runbook to enable a single Load Balancer for all the VMs in the recovery plan'
    }
    {
      name: 'ASR-AddMulitpleLoadBalancers'
      url: uri(_artifactsLocation, 'scripts/ASR-AddMultipleLoadBalancers.ps1${_artifactsLocationSasToken}')
      version: '1.0.0.0'
      type: 'PowerShell'
      description: 'ASR Runbook to enable multiple Load Balancers for selected VMs in the recovery plan'
    }
    {
      name: 'ASR-DNS-UpdateIP'
      url: uri(_artifactsLocation, 'scripts/ASR-DNS-UpdateIP.ps1${_artifactsLocationSasToken}')
      version: '1.0.0.0'
      type: 'PowerShellWorkflow'
      description: 'ASR Runbook to update DNS for VMs within the recovery plan'
    }
    {
      name: 'ASR-Wordpress-ChangeMysqlConfig'
      url: uri(_artifactsLocation, 'scripts/ASR-Wordpress-ChangeMysqlConfig.ps1${_artifactsLocationSasToken}')
      version: '1.0.0.0'
      type: 'PowerShellWorkflow'
      description: 'ASR Runbook to configure Mysql as part of a recovery plan'
    }
    {
      name: 'ASR-SQL-FailoverAGClassic'
      url: uri(_artifactsLocation, 'scripts/ASR-SQL-FailoverAGClassic.ps1${_artifactsLocationSasToken}')
      version: '1.0.0.0'
      type: 'PowerShellWorkflow'
      description: 'ASR Runbook to failover SQL Availability Groups'
    }
  ]
  modules: [
    {
      name: 'AzureRm.Compute'
      url: uri(modulesUri, 'azurerm.compute.2.8.0.nupkg')
    }
    {
      name: 'AzureRm.Resources'
      url: uri(modulesUri, 'azurerm.resources.3.7.0.nupkg')
    }
    {
      name: 'AzureRm.Network'
      url: uri(modulesUri, 'azurerm.network.3.6.0.nupkg')
    }
    {
      name: 'AzureRm.Automation'
      url: uri(modulesUri, 'azurerm.automation.1.0.3.nupkg')
    }
  ]
}
var azureRmProfile = {
  name: 'AzureRm.Profile'
  url: uri(modulesUri, 'azurerm.profile.2.7.0.nupkg')
}

resource automationAccount 'Microsoft.Automation/automationAccounts@2022-08-08' = {
  name: automationAccountName
  location: automationRegion
  properties: {
    sku: {
      name: 'Basic'
    }
  }
}

resource accountVariable 'Microsoft.Automation/automationAccounts/variables@2022-08-08' = {
  parent: automationAccount
  name: assets.aaVariables.AzureSubscriptionId.name
  properties: {
    description: assets.aaVariables.AzureSubscriptionId.description
    value: '"${subscription().subscriptionId}"'
  }
}

resource accountRunbook 'Microsoft.Automation/automationAccounts/runbooks@2022-08-08' = [for i in range(0, length(asrScripts.runbooks)): {
  name: '${automationAccountName}/${asrScripts.runbooks[i].Name}'
  location: automationRegion
  properties: {
    description: asrScripts.runbooks[i].description
    runbookType: asrScripts.runbooks[i].type
    logProgress: false
    logVerbose: true
    publishContentLink: {
      uri: asrScripts.runbooks[i].url
      version: asrScripts.runbooks[i].version
    }
  }
  dependsOn: [
    automationAccount
  ]
}]

resource profileModule 'Microsoft.Automation/automationAccounts/modules@2022-08-08' = {
  parent: automationAccount
  name: azureRmProfile.name
  location: automationRegion
  properties: {
    contentLink: {
      uri: azureRmProfile.url
    }
  }
}

resource scriptModule 'Microsoft.Automation/automationAccounts/modules@2022-08-08' = [for i in range(0, length(asrScripts.modules)): {
  name: '${automationAccountName}/${asrScripts.modules[i].Name}'
  location: automationRegion
  properties: {
    contentLink: {
      uri: asrScripts.modules[i].url
    }
  }
  dependsOn: [
    automationAccount
    profileModule
  ]
}]

@description('Name of the existing VNET to inject Cloud Shell into.')
param existingVNETName string

@description('Name of Azure Relay Namespace.')
param relayNamespaceName string

@description('Name of Network Security Group.')
param nsgName string

@description('Object Id of Azure Container Instance Service Principal. We have to grant this permission to create hybrid connections in the Azure Relay you specify. To get it: Get-AzADServicePrincipal -DisplayNameBeginsWith 'Azure Container Instance'')
param azureContainerInstanceOID string

@description('Name of the subnet to use for Cloud Shell containers.')
param containerSubnetName string = 'cloudshellsubnet'

@description('Address space of the subnet to add for Cloud Shell. e.g. 10.0.1.0/26')
param containerSubnetAddressPrefix string

@description('Name of the subnet to use for private link of relay namespace.')
param relaySubnetName string = 'relaysubnet'

@description('Address space of the subnet to add for relay. e.g. 10.0.2.0/26')
param relaySubnetAddressPrefix string

@description('Name of the subnet to use for storage account.')
param storageSubnetName string = 'storagesubnet'

@description('Address space of the subnet to add for storage. e.g. 10.0.3.0/26')
param storageSubnetAddressPrefix string

@description('Name of Private Endpoint for Azure Relay.')
param privateEndpointName string = 'cloudshellRelayEndpoint'

@description('Name of the resource tag.')
param tagName object = {
  Environment: 'cloudshell'
}

@description('Location for all resources.')
param location string = resourceGroup().location

var networkProfileName = 'aci-networkProfile-${location}'
var contributorRoleDefinitionId = resourceId(
  'Microsoft.Authorization/roleDefinitions',
  'b24988ac-6180-42a0-ab88-20f7382dd24c'
)
var networkRoleDefinitionId = resourceId(
  'Microsoft.Authorization/roleDefinitions',
  '4d97b98b-1d4f-4787-a291-c67834d212e7'
)
var privateDnsZoneName = ((toLower(environment().name) == 'azureusgovernment')
  ? 'privatelink.servicebus.usgovcloudapi.net'
  : 'privatelink.servicebus.windows.net')
var vnetResourceId = resourceId('Microsoft.Network/virtualNetworks', existingVNETName)

resource existingVNET 'Microsoft.Network/virtualNetworks@2023-05-01' existing = {
  name: existingVNETName
}

resource existingVNET_roleAssignment 'Microsoft.Authorization/roleAssignments@2022-04-01' = {
  scope: existingVNET
  name: guid(networkRoleDefinitionId, azureContainerInstanceOID, vnetResourceId)
  properties: {
    roleDefinitionId: networkRoleDefinitionId
    principalId: azureContainerInstanceOID
  }
}

resource containerSubnet 'Microsoft.Network/virtualNetworks/subnets@2023-05-01' = {
  parent: existingVNET
  name: containerSubnetName
  properties: {
    addressPrefix: containerSubnetAddressPrefix
    serviceEndpoints: [
      {
        service: 'Microsoft.Storage'
        locations: [
          location
        ]
      }
    ]
    delegations: [
      {
        name: 'CloudShellDelegation'
        properties: {
          serviceName: 'Microsoft.ContainerInstance/containerGroups'
        }
      }
    ]
    networkSecurityGroup: {
      id: networkSecurityGroup.id
    }
  }
}

resource networkSecurityGroupDefaultRules 'Microsoft.Network/networkSecurityGroups/defaultSecurityRules@2023-05-01' existing = {
  name: nsgName
  parent: networkSecurityGroup
}

resource networkSecurityGroup 'Microsoft.Network/networkSecurityGroups@2023-05-01' = {
  name: nsgName
  location: location
  properties: {
    securityRules: [
      {
        id: resourceId('Microsoft.Network/networkSecurityGroups', nsgName)
        name: 'DenyIntraSubnetTraffic'
        properties: {
          description: 'Deny traffic between container groups in cloudshellsubnet'
          protocol: '*'
          sourcePortRange: '*'
          destinationPortRange: '*'
          sourceAddressPrefix: containerSubnetAddressPrefix
          destinationAddressPrefix: containerSubnetAddressPrefix
          access: 'Deny'
          priority: 100
          direction: 'Inbound'
        }
      }
    ]
  }
}

resource networkProfile 'Microsoft.Network/networkProfiles@2023-05-01' = {
  name: networkProfileName
  tags: tagName
  location: location
  properties: {
    containerNetworkInterfaceConfigurations: [
      {
        name: 'eth-${containerSubnetName}'
        properties: {
          ipConfigurations: [
            {
              name: 'ipconfig-${containerSubnetName}'
              properties: {
                subnet: {
                  id: containerSubnet.id
                }
              }
            }
          ]
        }
      }
    ]
  }
}

resource networkProfile_roleAssignment 'Microsoft.Authorization/roleAssignments@2022-04-01' = {
  scope: networkProfile
  name: guid(networkRoleDefinitionId, azureContainerInstanceOID, networkProfile.name)
  properties: {
    roleDefinitionId: networkRoleDefinitionId
    principalId: azureContainerInstanceOID
  }
}

resource relayNamespace 'Microsoft.Relay/namespaces@2021-11-01' = {
  name: relayNamespaceName
  tags: tagName
  location: location
  sku: {
    name: 'Standard'
    tier: 'Standard'
  }
}

resource relayNamespace_roleAssignment 'Microsoft.Authorization/roleAssignments@2022-04-01' = {
  scope: relayNamespace
  name: guid(contributorRoleDefinitionId, azureContainerInstanceOID, relayNamespace.name)
  properties: {
    roleDefinitionId: contributorRoleDefinitionId
    principalId: azureContainerInstanceOID
  }
}

resource relaySubnet 'Microsoft.Network/virtualNetworks/subnets@2023-05-01' = {
  parent: existingVNET
  name: relaySubnetName
  properties: {
    addressPrefix: relaySubnetAddressPrefix
    privateEndpointNetworkPolicies: 'Disabled'
    privateLinkServiceNetworkPolicies: 'Enabled'
    networkSecurityGroup: {
      id: networkSecurityGroup.id
    }
  }
  dependsOn: [
    containerSubnet
  ]
}

resource privateEndpoint 'Microsoft.Network/privateEndpoints@2023-05-01' = {
  name: privateEndpointName
  tags: tagName
  location: location
  properties: {
    privateLinkServiceConnections: [
      {
        name: privateEndpointName
        properties: {
          privateLinkServiceId: relayNamespace.id
          groupIds: [
            'namespace'
          ]
        }
      }
    ]
    subnet: {
      id: relaySubnet.id
    }
  }
}

resource storageSubnet 'Microsoft.Network/virtualNetworks/subnets@2023-05-01' = {
  parent: existingVNET
  name: storageSubnetName
  properties: {
    addressPrefix: storageSubnetAddressPrefix
    serviceEndpoints: [
      {
        service: 'Microsoft.Storage'
        locations: [
          location
        ]
      }
    ]
    networkSecurityGroup: {
      id: networkSecurityGroup.id
    }
  }
  dependsOn: [
    relaySubnet
  ]
}

resource privateDnsZone 'Microsoft.Network/privateDnsZones@2020-06-01' = {
  name: privateDnsZoneName
  tags: tagName
  location: 'global'
}

resource privateDnsZoneARecord 'Microsoft.Network/privateDnsZones/A@2020-06-01' = {
  parent: privateDnsZone
  name: relayNamespaceName
  properties: {
    ttl: 3600
    aRecords: [
      {
        ipv4Address: first(first(privateEndpoint.properties.customDnsConfigs).ipAddresses)
      }
    ]
  }
}

resource privateDnsZoneVnetLink 'Microsoft.Network/privateDnsZones/virtualNetworkLinks@2020-06-01' = {
  parent: privateDnsZone
  name: relayNamespaceName
  tags: tagName
  location: 'global'
  properties: {
    registrationEnabled: false
    virtualNetwork: {
      id: vnetResourceId
    }
  }
}

output vnetId string = vnetResourceId
output containerSubnetId string = containerSubnet.id
output storageSubnetId string = storageSubnet.id
output networkSecurityGroupResourceId string = networkSecurityGroup.id
output nsgDefaultRules string = networkSecurityGroupDefaultRules.id

@description('Name of the virtual network to use for cloud shell containers.')
param existingVNETName string

@description('Name of the subnet to use for storage account.')
param existingStorageSubnetName string

@description('Name of the subnet to use for cloud shell containers.')
param existingContainerSubnetName string

@description('Name of the storage account in subnet.')
param storageAccountName string

@description('Name of the fileshare in storage account.')
param fileShareName string = 'acsshare'

@description('Name of the resource tag')
param resourceTags object = {
  Environment: 'cloudshell'
}

@description('Location for all resources.')
param location string = resourceGroup().location

var containerSubnetRef = resourceId(
  'Microsoft.Network/virtualNetworks/subnets',
  existingVNETName,
  existingContainerSubnetName
)
var storageSubnetRef = resourceId(
  'Microsoft.Network/virtualNetworks/subnets',
  existingVNETName,
  existingStorageSubnetName
)

resource storageAccount 'Microsoft.Storage/storageAccounts@2021-09-01' = {
  name: storageAccountName
  tags: resourceTags
  location: location
  sku: {
    name: 'Standard_LRS'
  }
  kind: 'StorageV2'
  properties: {
    networkAcls: {
      bypass: 'None'
      virtualNetworkRules: [
        {
          id: containerSubnetRef
          action: 'Allow'
        }
        {
          id: storageSubnetRef
          action: 'Allow'
        }
      ]
      defaultAction: 'Deny'
    }
    supportsHttpsTrafficOnly: true
    encryption: {
      services: {
        file: {
          keyType: 'Account'
          enabled: true
        }
        blob: {
          keyType: 'Account'
          enabled: true
        }
      }
      keySource: 'Microsoft.Storage'
    }
    accessTier: 'Cool'
  }
}

resource blobServices 'Microsoft.Storage/storageAccounts/blobServices@2021-09-01' = {
  parent: storageAccount
  name: 'default'
  properties: {
    deleteRetentionPolicy: {
      enabled: false
    }
  }
}

resource fileServices 'Microsoft.Storage/storageAccounts/fileServices@2021-09-01' = {
  parent: storageAccount
  name: 'default'
}

resource fileShare 'Microsoft.Storage/storageAccounts/fileServices/shares@2021-09-01' = {
  parent: fileServices
  name: fileShareName
  properties: {
    shareQuota: 6
  }
}

@description('Type of the Storage for disks')
@allowed([
  'Standard_LRS'
  'StandardSSD_LRS'
  'Premium_LRS'
])
param diskType string = 'StandardSSD_LRS'

@description('Name of the VM')
param vmName string = 'iis'

@description('Size of the VM')
param vmSize string = 'Standard_A2_v2'

@description('Image SKU')
@allowed([
  '2012-R2-Datacenter'
  '2016-Datacenter'
  '2019-Datacenter'
])
param imageSKU string = '2019-Datacenter'

@description('Admin username')
param adminUsername string

@description('Admin password')
@secure()
param adminPassword string

@description('Relative path for the DSC configuration module.')
param moduleFilePath string = 'ContosoWebsite.ps1.zip'

@description('DSC configuration function to call')
param configurationFunction string = 'ContosoWebsite.ps1\ContosoWebsite'

@description('The base URI where artifacts required by this template are located. When the template is deployed using the accompanying scripts, a private location in the subscription will be used and this value will be automatically generated.')
param _artifactsLocation string = deployment().properties.templateLink.uri

@description('The sasToken required to access _artifactsLocation.  When the template is deployed using the accompanying scripts, a sasToken will be automatically generated.')
@secure()
param _artifactsLocationSasToken string = ''

@description('Location for all resources.')
param location string = resourceGroup().location

var virtualNetworkName = 'dscVNET'
var vnetAddressPrefix = '10.0.0.0/16'
var subnet1Name = 'dscSubnet-1'
var subnet1Prefix = '10.0.0.0/24'
var subnet1Ref = resourceId('Microsoft.Network/virtualNetworks/subnets', virtualNetworkName, subnet1Name)
var publicIPAddressType = 'Dynamic'
var publicIPAddressName = 'dscPubIP'
var nicName = 'dscNIC'
var imagePublisher = 'MicrosoftWindowsServer'
var imageOffer = 'WindowsServer'
var vmExtensionName = 'dscExtension'
var networkSecurityGroupName = 'default-NSG'

resource publicIPAddress 'Microsoft.Network/publicIPAddresses@2023-09-01' = {
  name: publicIPAddressName
  location: location
  properties: {
    publicIPAllocationMethod: publicIPAddressType
  }
}

resource networkSecurityGroup 'Microsoft.Network/networkSecurityGroups@2023-09-01' = {
  name: networkSecurityGroupName
  location: location
  properties: {
    securityRules: [
      {
        name: 'default-allow-80'
        properties: {
          priority: 1000
          access: 'Allow'
          direction: 'Inbound'
          destinationPortRange: '80'
          protocol: 'Tcp'
          sourceAddressPrefix: '*'
          sourcePortRange: '*'
          destinationAddressPrefix: '*'
        }
      }
      {
        name: 'default-allow-443'
        properties: {
          priority: 1001
          access: 'Allow'
          direction: 'Inbound'
          destinationPortRange: '443'
          protocol: 'Tcp'
          sourceAddressPrefix: '*'
          sourcePortRange: '*'
          destinationAddressPrefix: '*'
        }
      }
      {
        name: 'default-allow-3389'
        properties: {
          priority: 1002
          access: 'Allow'
          direction: 'Inbound'
          destinationPortRange: '3389'
          protocol: 'Tcp'
          sourceAddressPrefix: '*'
          sourcePortRange: '*'
          destinationAddressPrefix: '*'
        }
      }
    ]
  }
}

resource virtualNetwork 'Microsoft.Network/virtualNetworks@2023-09-01' = {
  name: virtualNetworkName
  location: location
  properties: {
    addressSpace: {
      addressPrefixes: [
        vnetAddressPrefix
      ]
    }
    subnets: [
      {
        name: subnet1Name
        properties: {
          addressPrefix: subnet1Prefix
          networkSecurityGroup: {
            id: networkSecurityGroup.id
          }
        }
      }
    ]
  }
}

resource nic 'Microsoft.Network/networkInterfaces@2023-09-01' = {
  name: nicName
  location: location
  properties: {
    ipConfigurations: [
      {
        name: 'ipconfig1'
        properties: {
          privateIPAllocationMethod: 'Dynamic'
          publicIPAddress: {
            id: publicIPAddress.id
          }
          subnet: {
            id: subnet1Ref
          }
        }
      }
    ]
  }
  dependsOn: [

    virtualNetwork
  ]
}

resource vm 'Microsoft.Compute/virtualMachines@2023-09-01' = {
  name: vmName
  location: location
  properties: {
    hardwareProfile: {
      vmSize: vmSize
    }
    osProfile: {
      computerName: vmName
      adminUsername: adminUsername
      adminPassword: adminPassword
    }
    storageProfile: {
      imageReference: {
        publisher: imagePublisher
        offer: imageOffer
        sku: imageSKU
        version: 'latest'
      }
      osDisk: {
        name: '${vmName}_OSDisk'
        caching: 'ReadWrite'
        createOption: 'FromImage'
        managedDisk: {
          storageAccountType: diskType
        }
      }
    }
    networkProfile: {
      networkInterfaces: [
        {
          id: nic.id
        }
      ]
    }
  }
}

resource vmName_vmExtension 'Microsoft.Compute/virtualMachines/extensions@2023-09-01' = {
  parent: vm
  name: vmExtensionName
  location: location
  properties: {
    publisher: 'Microsoft.Powershell'
    type: 'DSC'
    typeHandlerVersion: '2.19'
    autoUpgradeMinorVersion: true
    settings: {
      ModulesUrl: uri(_artifactsLocation, '${moduleFilePath}${_artifactsLocationSasToken}')
      ConfigurationFunction: configurationFunction
      Properties: {
        MachineName: vmName
      }
    }
  }
}

@description('Prefix for the environment (2-5 characters)')
