@description('CDN SKU names')
@allowed([
  'Standard_Akamai'
  'Standard_Verizon'
  'Premium_Verizon'
  'Standard_Microsoft'
])
param CDNSku string = 'Standard_Microsoft'

@description('Location for all resources.')
param location string = resourceGroup().location

resource profile 'Microsoft.Cdn/profiles@2021-06-01' = {
  name: profileName
  location: location
  sku: {
    name: CDNSku
  }
}

resource endpoint 'Microsoft.Cdn/profiles/endpoints@2021-06-01' = {
  parent: profile
  location: location
  name: endpointName
  properties: {
    originHostHeader: originUrl
    isHttpAllowed: true
    isHttpsAllowed: true
    queryStringCachingBehavior: 'IgnoreQueryString'
    contentTypesToCompress: [
      'text/plain'
      'text/html'
      'text/css'
      'application/x-javascript'
      'text/javascript'
    ]
    isCompressionEnabled: true
    origins: [
      {
        name: 'origin1'
        properties: {
          hostName: originUrl
        }
      }
    ]
    deliveryPolicy: {
      description: 'Path based Cache Override'
      rules: [
        {
          name: 'Pathmatchcondition'
          order: 1
          conditions: [
            {
              name: 'UrlPath'
              parameters: {
                typeName: 'DeliveryRuleUrlPathMatchConditionParameters'
                operator: 'BeginsWith'
                matchValues: [
                  '/images/'
                ]
              }
            }
          ]
          actions: [
            {
              name: 'CacheExpiration'
              parameters: {
                typeName: 'DeliveryRuleCacheExpirationActionParameters'
                cacheBehavior: 'Override'
                cacheType: 'All'
                cacheDuration: '00:00:30'
              }
            }
          ]
        }
      ]
    }
  }
}

@description('Name of the CDN Profile')
param profileName string

@description('Name of the CDN Endpoint')
param endpointName string

@description('Url of the origin')
param originUrl string

@description('CDN SKU names')
@allowed([
  'Standard_Akamai'
  'Standard_Verizon'
  'Premium_Verizon'
  'Standard_Microsoft'
])
param CDNSku string = 'Standard_Microsoft'

@description('Location for all resources.')
param location string = resourceGroup().location

resource profile 'Microsoft.Cdn/profiles@2021-06-01' = {
  name: profileName
  location: location
  sku: {
    name: CDNSku
  }
}

resource endpoint 'Microsoft.Cdn/profiles/endpoints@2021-06-01' = {
  parent: profile
  name: endpointName
  location: location
  properties: {
    originHostHeader: originUrl
    isHttpAllowed: true
    isHttpsAllowed: true
    queryStringCachingBehavior: 'IgnoreQueryString'
    contentTypesToCompress: [
      'text/plain'
      'text/html'
      'text/css'
      'application/x-javascript'
      'text/javascript'
    ]
    isCompressionEnabled: true
    origins: [
      {
        name: 'origin1'
        properties: {
          hostName: originUrl
        }
      }
    ]
    deliveryPolicy: {
      description: 'Add Response Headers'
      rules: [
        {
          name: 'GeoMatchCondition'
          order: 1
          conditions: [
            {
              name: 'RemoteAddress'
              parameters: {
                typeName: 'DeliveryRuleRemoteAddressConditionParameters'
                operator: 'GeoMatch'
                matchValues: [
                  'US'
                ]
              }
            }
          ]
          actions: [
            {
              name: 'ModifyResponseHeader'
              parameters: {
                typeName: 'DeliveryRuleHeaderActionParameters'
                headerAction: 'Overwrite'
                headerName: 'X-CLIENT-COUNTRY'
                value: 'US'
              }
            }
          ]
        }
        {
          name: 'IPv4Match'
          order: 2
          conditions: [
            {
              name: 'RemoteAddress'
              parameters: {
                typeName: 'DeliveryRuleRemoteAddressConditionParameters'
                operator: 'IPMatch'
                matchValues: [
                  '0.0.0.0/0'
                ]
              }
            }
          ]
          actions: [
            {
              name: 'ModifyResponseHeader'
              parameters: {
                typeName: 'DeliveryRuleHeaderActionParameters'
                headerAction: 'Overwrite'
                headerName: 'X-CLIENT-IP-VERSION'
                value: 'IPv4'
              }
            }
          ]
        }
        {
          name: 'IPv6Match'
          order: 3
          conditions: [
            {
              name: 'RemoteAddress'
              parameters: {
                typeName: 'DeliveryRuleRemoteAddressConditionParameters'
                operator: 'IPMatch'
                matchValues: [
                  '::0/0'
                ]
              }
            }
          ]
          actions: [
            {
              name: 'ModifyResponseHeader'
              parameters: {
                typeName: 'DeliveryRuleHeaderActionParameters'
                headerAction: 'Overwrite'
                headerName: 'X-CLIENT-IP-VERSION'
                value: 'IPv6'
              }
            }
          ]
        }
      ]
    }
  }
}

@description('Name of the CDN Profile')
param profileName string

@description('Name of the CDN Endpoint')
param endpointName string

@description('Url of the origin')
param originUrl string

@description('CDN SKU names')
@allowed([
  'Standard_Akamai'
  'Standard_Verizon'
  'Premium_Verizon'
  'Standard_Microsoft'
])
param CDNSku string = 'Standard_Microsoft'

@description('Location for all resources.')
param location string = resourceGroup().location

resource profile 'Microsoft.Cdn/profiles@2021-06-01' = {
  name: profileName
  location: location
  sku: {
    name: CDNSku
  }
}

resource endpoint 'Microsoft.Cdn/profiles/endpoints@2021-06-01' = {
  parent: profile
  location: location
  name: endpointName
  properties: {
    originHostHeader: originUrl
    isHttpAllowed: true
    isHttpsAllowed: true
    queryStringCachingBehavior: 'IgnoreQueryString'
    contentTypesToCompress: [
      'text/plain'
      'text/html'
      'text/css'
      'application/x-javascript'
      'text/javascript'
    ]
    isCompressionEnabled: true
    origins: [
      {
        name: 'origin1'
        properties: {
          hostName: originUrl
        }
      }
    ]
    deliveryPolicy: {
      description: 'Rewrite and Redirect'
      rules: [
        {
          name: 'PathRewriteBasedOnDeviceMatchCondition'
          order: 1
          conditions: [
            {
              name: 'IsDevice'
              parameters: {
                typeName: 'DeliveryRuleIsDeviceConditionParameters'
                operator: 'Equal'
                matchValues: [
                  'Mobile'
                ]
              }
            }
          ]
          actions: [
            {
              name: 'UrlRewrite'
              parameters: {
                typeName: 'DeliveryRuleUrlRewriteActionParameters'
                sourcePattern: '/standard'
                destination: '/mobile'
              }
            }
          ]
        }
        {
          name: 'HttpVersionBasedRedirect'
          order: 2
          conditions: [
            {
              name: 'RequestScheme'
              parameters: {
                typeName: 'DeliveryRuleRequestSchemeConditionParameters'
                operator: 'Equal'
                matchValues: [
                  'HTTP'
                ]
              }
            }
          ]
          actions: [
            {
              name: 'UrlRedirect'
              parameters: {
                typeName: 'DeliveryRuleUrlRedirectActionParameters'
                redirectType: 'Found'
                destinationProtocol: 'Https'
              }
            }
          ]
        }
      ]
    }
  }
}

@description('Name of the CDN Profile')
param profileName string

@description('Name of the CDN Endpoint')
param endpointName string

@description('Url of the origin')
param originUrl string

@description('Subscription Id of UrlSigning Keys')
param urlSigningKeysSubId string

@description('Resourcegroup of UrlSigning Keys')
param urlSigningKeysResourceGroup string

@description('Keyvault of UrlSigning Keys')
param urlSigningKeysVaultName string

@description('UrlSigning keys secret1 Name')
param urlSigningKeysSecret1Name string

@description('UrlSigning keys secret1 version')
param urlSigningKeysSecret1Version string

@description('UrlSigning keys secret2 Name')
param urlSigningKeysSecret2Name string

@description('UrlSigning keys secret2 version')
param urlSigningKeysSecret2Version string

@description('CDN SKU names')
@allowed([
  'Standard_Akamai'
  'Standard_Verizon'
  'Premium_Verizon'
  'Standard_Microsoft'
])
param CDNSku string = 'Standard_Microsoft'

@description('Location for all resources.')
param location string = resourceGroup().location

resource profile 'Microsoft.Cdn/profiles@2021-06-01' = {
  name: profileName
  location: location
  sku: {
    name: CDNSku
  }
}

resource endpoint 'Microsoft.Cdn/profiles/endpoints@2021-06-01' = {
  parent: profile
  location: location
  name: endpointName
  properties: {
    originHostHeader: originUrl
    isHttpAllowed: true
    isHttpsAllowed: true
    queryStringCachingBehavior: 'UseQueryString'
    contentTypesToCompress: [
      'text/plain'
      'text/html'
      'text/css'
      'application/x-javascript'
      'text/javascript'
    ]
    isCompressionEnabled: true
    origins: [
      {
        name: 'origin1'
        properties: {
          hostName: originUrl
        }
      }
    ]
    urlSigningKeys: [
      {
        keyId: 'key1'
        keySourceParameters: {
          typeName: 'KeyVaultSigningKeyParameters'
          subscriptionId: urlSigningKeysSubId
          resourceGroupName: urlSigningKeysResourceGroup
          vaultName: urlSigningKeysVaultName
          secretName: urlSigningKeysSecret1Name
          secretVersion: urlSigningKeysSecret1Version
        }
      }
      {
        keyId: 'key2'
        keySourceParameters: {
          typeName: 'KeyVaultSigningKeyParameters'
          subscriptionId: urlSigningKeysSubId
          resourceGroupName: urlSigningKeysResourceGroup
          vaultName: urlSigningKeysVaultName
          secretName: urlSigningKeysSecret2Name
          secretVersion: urlSigningKeysSecret2Version
        }
      }
    ]
    deliveryPolicy: {
      description: 'UrlSigning'
      rules: [
        {
          name: 'rule1'
          order: 1
          conditions: [
            {
              name: 'UrlPath'
              parameters: {
                operator: 'Equal'
                matchValues: [
                  '/urlsigning/test'
                ]
                typeName: 'DeliveryRuleUrlPathMatchConditionParameters'
              }
            }
          ]
          actions: [
            {
              name: 'UrlSigning'
              parameters: {
                keyId: 'key1'
                algorithm: 'SHA256'
                typeName: 'DeliveryRuleUrlSigningActionParameters'
              }
            }
            {
              name: 'CacheKeyQueryString'
              parameters: {
                queryStringBehavior: 'Exclude'
                queryParameters: 'expires,keyid,signature'
                typeName: 'DeliveryRuleCacheKeyQueryStringBehaviorActionParameters'
              }
            }
          ]
        }
        {
          name: 'rule2'
          order: 2
          conditions: [
            {
              name: 'UrlPath'
              parameters: {
                operator: 'Equal'
                matchValues: [
                  '/urlsigning/test2'
                ]
                typeName: 'DeliveryRuleUrlPathMatchConditionParameters'
              }
            }
          ]
          actions: [
            {
              name: 'UrlSigning'
              parameters: {
                keyId: 'key2'
                algorithm: 'SHA256'
                parameterNameOverride: [
                  {
                    paramIndicator: 'Expires'
                    paramName: 'oexpires'
                  }
                  {
                    paramIndicator: 'KeyId'
                    paramName: 'okeyid'
                  }
                  {
                    paramIndicator: 'Signature'
                    paramName: 'osignature'
                  }
                ]
                typeName: 'DeliveryRuleUrlSigningActionParameters'
              }
            }
            {
              name: 'CacheKeyQueryString'
              parameters: {
                queryStringBehavior: 'Exclude'
                queryParameters: 'oexpires,okeyid,osignature'
                typeName: 'DeliveryRuleCacheKeyQueryStringBehaviorActionParameters'
              }
            }
          ]
        }
      ]
    }
  }
}

