param location string

param recoveryServiceVaultName string
param backupPolicyName string = 'DailyPolicy-${uniqueString(resourceGroup().id)}'
param storageAccountId string
param fileShareName string
param timeZone string = 'Central Standard Time'


resource recoveryServiceVault 'Microsoft.RecoveryServices/vaults@2024-04-30-preview' = {
  name: recoveryServiceVaultName
  location: location
  sku: {
    name: 'RS0'
    tier: 'Standard'
  }
  properties: {
    redundancySettings: {
      crossRegionRestore: 'Disabled'
      standardTierStorageRedundancy: 'GeoRedundant'
    }
    publicNetworkAccess: 'Enabled'
  }
}

resource backupPolicies 'Microsoft.RecoveryServices/vaults/backupPolicies@2024-04-30-preview' = {
  parent: recoveryServiceVault
  location: location
  name: backupPolicyName
  properties: {
    backupManagementType: 'AzureStorage'
    workLoadType: 'AzureFileShare'
    protectedItemsCount: 0
    timeZone: timeZone
    schedulePolicy: {
      schedulePolicyType: 'SimpleSchedulePolicy'
      scheduleRunFrequency: 'Daily'
      scheduleWeeklyFrequency: 0
      scheduleRunTimes: [
        '05:30'
      ]
    }
    retentionPolicy: {
      retentionPolicyType: 'LongTermRetentionPolicy'
      dailySchedule: {
        retentionTimes: [
          '05:30'
        ]
        retentionDuration: {
          count: 30
          durationType: 'Days'
        }
      }
    }
  }
}

resource protectionContainers 'Microsoft.RecoveryServices/vaults/backupFabrics/protectionContainers@2024-04-30-preview' = {
  location: location
  name: format('{0}/{1}/storagecontainer;Storage;{2};{3}', recoveryServiceVault.name, 'Azure', split(storageAccountId, '/')[4], split(storageAccountId, '/')[8])
  properties: {
    backupManagementType: 'AzureStorage'
    containerType: 'StorageContainer'
    sourceResourceId: storageAccountId
  }
}

resource protectedItems 'Microsoft.RecoveryServices/vaults/backupFabrics/protectionContainers/protectedItems@2024-04-30-preview' = {
  parent: protectionContainers
  location: location
  name: 'AzureFileShare;${fileShareName}'
  properties: {
    protectedItemType: 'AzureFileShareProtectedItem'
    sourceResourceId: storageAccountId
    policyId: backupPolicies.id
  }
}

param location string
param fslogixEnabled bool

param subnetId string
param numberOfSessionHost int = 2
param virtualMachine object
@secure()
param adminUsername string
@secure()
param adminPassword string
param hostPoolName string
param activeDirectoryAuthenticationEnabled bool
param DomainName string?
param DomainJoinOUPath string?
param ADAdministratorAccountUsername string?
@secure()
param ADAdministratorAccountPassword string?
param artifactsLocation string
param hostPoolRegistrationInfoToken string

resource networkInterface 'Microsoft.Network/networkInterfaces@2024-01-01' = [for i in range(0, numberOfSessionHost) : {
  location: location
  name: '${virtualMachine.name}-nic${i + 1}'
  properties: {
    enableAcceleratedNetworking: true
    ipConfigurations: [
      {
        name: 'ipConfig'
        properties: {
          privateIPAllocationMethod: 'Dynamic'
          subnet: {
            id: subnetId
          }
        }
      }
    ]
  }
}]

resource vms 'Microsoft.Compute/virtualMachines@2024-03-01' = [for i in range(0, numberOfSessionHost) : {
  location: location
  name: '${virtualMachine.name}${i + 1}'
  properties: {
    licenseType: virtualMachine.licenseType
    hardwareProfile: {
      vmSize: virtualMachine.vmSize
    }
    storageProfile: {
      osDisk: {
        createOption: virtualMachine.osDisk.createOption
        managedDisk: {
          storageAccountType: virtualMachine.osDisk.storageAccountType
        }
        deleteOption: virtualMachine.osDisk.deleteOption
      }
      imageReference: {
        publisher: virtualMachine.imageReference.publisher
        offer: virtualMachine.imageReference.offer
        sku: virtualMachine.imageReference.sku
        version: virtualMachine.imageReference.version
      }
    }
    networkProfile: {
      networkInterfaces: [
        {
          id: networkInterface[i].id
          properties: {
            deleteOption: 'Delete'
          }
        }
      ]
    }
    securityProfile: {
      securityType: 'TrustedLaunch'
      uefiSettings: {
        secureBootEnabled: true
        vTpmEnabled: true
      }
    }
    additionalCapabilities: {
      hibernationEnabled: false
    }
    osProfile: {
      computerName: '${virtualMachine.name}${i + 1}'
      adminUsername: adminUsername
      adminPassword: adminPassword
    }
    diagnosticsProfile: {
      bootDiagnostics: {
        enabled: true
      }
    }
  }
}]

resource entraIdJoin 'Microsoft.Compute/virtualMachines/extensions@2024-03-01' = [for i in range(0, numberOfSessionHost) : if (!activeDirectoryAuthenticationEnabled || !fslogixEnabled) {
  parent: vms[i]
  name: 'AADLoginForWindows'
  location: location
  properties: {
    publisher: 'Microsoft.Azure.ActiveDirectory'
    type: 'AADLoginForWindows'
    typeHandlerVersion: '1.0'
    autoUpgradeMinorVersion: true
    enableAutomaticUpgrade: false
  }
}]

resource dcs 'Microsoft.Compute/virtualMachines/extensions@2024-03-01' = [for i in range(0, numberOfSessionHost) : {
  parent: vms[i]
  name: 'MicrosoftPowershellDSC'
  location: location
  properties: {
    publisher: 'Microsoft.Powershell'
    type: 'DSC'
    typeHandlerVersion: '2.83'
    autoUpgradeMinorVersion: true
    settings: {
      modulesUrl: artifactsLocation
      configurationFunction: 'Configuration.ps1\AddSessionHost'
      properties: {
        hostPoolName: hostPoolName
        aadJoin: true
      }
    }
    protectedSettings: {
      properties: {
        registrationInfoToken: hostPoolRegistrationInfoToken
      }
    }
  }
  dependsOn: [
    entraIdJoin
  ]
}]

resource adomainJoin 'Microsoft.Compute/virtualMachines/extensions@2024-03-01' = [for i in range(0, numberOfSessionHost) :if (activeDirectoryAuthenticationEnabled || fslogixEnabled)  {
  parent: vms[i]
  name: 'ActiveDirectoryDomainJoin'
  location: location
  properties: {
    publisher: 'Microsoft.Compute'
    type: 'JsonADDomainExtension'
    typeHandlerVersion: '1.3'
    autoUpgradeMinorVersion: true
    settings: {
      name: DomainName
      ouPath: DomainJoinOUPath
      user: ADAdministratorAccountUsername
      restart: true
      options: 3
    }
    protectedSettings: {
      password: ADAdministratorAccountPassword
    }
  }
  dependsOn: [
    dcs
  ]
}]

param location string

param storageAccountName string
