  }
}

module backup '../recoveryservicevault/main.bicep' = {
  name: 'fileShareBackup'
  params: {
    location: location
    recoveryServiceVaultName: recoveryServiceVaultName
    storageAccountId: storageAccount.id
    fileShareName: fileShare.name
  }
}

