resource hubVnetToDevVnetPeering 'Microsoft.Network/virtualNetworks/virtualNetworkPeerings@2023-09-01' = {
  parent: hubVnet
  name: '${hubVnetName}To${devVnetName}Peering'
  properties: {
    allowVirtualNetworkAccess: true
