}]

@description('Storage Account Name')
param storageAccountName string

@description('Storage Account type')
@allowed([
  'Standard_LRS'
  'Standard_ZRS'
])
param storageAccountType string = 'Standard_LRS'

@description('Region')
@allowed([
  'northcentralus'
  'eastus2'
  'eastus2euap'
  'centralus'
  'canadaeast'
  'canadacentral'
  'northeurope'
  'australiaeast'
  'switzerlandnorth'
  'germanywestcentral'
  'eastasia'
  'francecentral'
])
param location string

@description('Username of primary user')
param userName string

@description('Home directory of primary user. Should be a container.')
param homeDirectory string

@description('SSH Public Key for primary user. If not specified, Azure will generate a password which can be accessed securely')
param publicKey string = ''

resource sa 'Microsoft.Storage/storageAccounts@2023-05-01' = {
  name: storageAccountName
  location: location
  sku: {
    name: storageAccountType
  }
  kind: 'StorageV2'
  properties: {
    isHnsEnabled: true
    isLocalUserEnabled: true
    isSftpEnabled: true
  }
}

resource container 'Microsoft.Storage/storageAccounts/blobServices/containers@2023-05-01' = {
  name: '${sa.name}/default/${homeDirectory}'
  properties: {
    publicAccess: 'None'
  }

}

resource user 'Microsoft.Storage/storageAccounts/localUsers@2023-05-01' = {
  parent: sa
  name: userName
  properties: {
    permissionScopes: [
      {
        permissions: 'rcwdl'
        service: 'blob'
        resourceName: homeDirectory
      }
    ]
    homeDirectory: homeDirectory
    sshAuthorizedKeys: empty(publicKey) ? null : [
      {
        description: '${userName} public key'
        key: publicKey
      }
    ]
    hasSharedKey: false
  }
}

// This template deploys an Azure Storage account, and then configures it to support static website hosting.
// Enabling static website hosting isn't possible directly in Bicep or an ARM template,
// so this sample uses a deployment script to enable the feature.

@description('The location into which the resources should be deployed.')
param location string = resourceGroup().location

@description('The name of the storage account to use for site hosting.')
param storageAccountName string = 'stor${uniqueString(resourceGroup().id)}'

@allowed([
  'Standard_LRS'
  'Standard_GRS'
  'Standard_ZRS'
  'Premium_LRS'
])
@description('The storage account sku name.')
param storageSku string = 'Standard_LRS'

@description('The path to the web index document.')
param indexDocumentPath string = 'index.html'

@description('The contents of the web index document.')
param indexDocumentContents string = '<h1>Example static website</h1>'

@description('The path to the web error document.')
param errorDocument404Path string = 'error.html'

@description('The contents of the web error document.')
param errorDocument404Contents string = '<h1>Example 404 error page</h1>'

resource contributorRoleDefinition 'Microsoft.Authorization/roleDefinitions@2018-01-01-preview' existing = {
  scope: subscription()
  // This is the Storage Account Contributor role, which is the minimum role permission we can give. See https://docs.microsoft.com/en-us/azure/role-based-access-control/built-in-roles#:~:text=17d1049b-9a84-46fb-8f53-869881c3d3ab
  name: '17d1049b-9a84-46fb-8f53-869881c3d3ab'
}

resource storageAccount 'Microsoft.Storage/storageAccounts@2021-06-01' = {
  name: storageAccountName
  location: location
  kind: 'StorageV2'
  sku: {
    name: storageSku
  }
}

resource managedIdentity 'Microsoft.ManagedIdentity/userAssignedIdentities@2018-11-30' = {
  name: 'DeploymentScript'
  location: location
}

resource roleAssignment 'Microsoft.Authorization/roleAssignments@2020-04-01-preview' = {
  scope: storageAccount
  name: guid(resourceGroup().id, managedIdentity.id, contributorRoleDefinition.id)
  properties: {
    roleDefinitionId: contributorRoleDefinition.id
    principalId: managedIdentity.properties.principalId
    principalType: 'ServicePrincipal'
  }
}

resource deploymentScript 'Microsoft.Resources/deploymentScripts@2020-10-01' = {
  name: 'deploymentScript'
  location: location
  kind: 'AzurePowerShell'
  identity: {
    type: 'UserAssigned'
    userAssignedIdentities: {
      '${managedIdentity.id}': {}
    }
  }
  dependsOn: [
    // we need to ensure we wait for the role assignment to be deployed before trying to access the storage account
    roleAssignment
  ]
  properties: {
    azPowerShellVersion: '3.0'
    scriptContent: loadTextContent('./scripts/enable-static-website.ps1')
    retentionInterval: 'PT4H'
    environmentVariables: [
      {
        name: 'ResourceGroupName'
        value: resourceGroup().name
      }
      {
        name: 'StorageAccountName'
        value: storageAccount.name
      }
      {
        name: 'IndexDocumentPath'
        value: indexDocumentPath
      }
      {
        name: 'IndexDocumentContents'
        value: indexDocumentContents
      }
      {
        name: 'ErrorDocument404Path'
        value: errorDocument404Path
      }
      {
        name: 'ErrorDocument404Contents'
        value: errorDocument404Contents
      }
    ]
  }
}

output staticWebsiteUrl string = storageAccount.properties.primaryEndpoints.web

@sys.description('The name of storage task.')
@minLength(3)
@maxLength(18)
param storageTaskName string

@sys.description('A description of the storage task.')
param description string

@sys.description('The region in which to create the storage task.')
param location string = resourceGroup().location

@sys.description('Locks the file for one day.')
param lockedUntilDate string = dateTimeAdd(utcNow(), 'P1D')

resource storageTask 'Microsoft.StorageActions/storageTasks@2023-01-01' = {
  name: storageTaskName
  location: location
  identity: {
    type: 'SystemAssigned'
  }
  properties: {
    action: {
      if: {
        condition: '[[endsWith(Name, '.docx')]]'
        operations: [
         {
            name: 'SetBlobImmutabilityPolicy'
            onSuccess: 'continue'
            onFailure: 'break'
            parameters: {
              untilDate: lockedUntilDate
              mode: 'locked'
            }
         }
         {
            name: 'SetBlobTags'
            onSuccess: 'continue'
            onFailure: 'break'
            parameters: {
                tagsetImmutabilityUpdatedBy: 'StorageTaskQuickstart'
            }     
         }
        ]
      }

    }
    description: description
    enabled: true
  }
}

@description('Location of the Disk Pool')
@allowed([
  'AustraliaEast'
  'CanadaCentral'
  'CentralUS'
  'EastUS'
  'JapanEast'
  'NorthEurope'
  'SouthCentralUS'
  'SoutheastAsia'
  'UKSouth'
  'WestEurope'
  'WestUS2'
])
param diskPoolLocation string

@description('Sku of the Disk Pool')
@allowed([
  'Basic_B1'
  'Standard_S1'
  'Premium_P1'
])
param diskPoolSku string = 'Standard_S1'

@description('Name of the Disk Pool')
@minLength(7)
@maxLength(30)
param diskPoolName string = 'diskpool-01'

@description('Availability zone to deploy the Disk Pool')
param diskPoolAvailabilityZone string

@description('Name of the managed disk (512 sector size) to create and export as an iSCSI LUN in the Disk Pool')
param existingManagedDiskName string = 'disk-1'

@description('Name of the iSCSI Target')
@minLength(5)
@maxLength(40)
param targetName string = 'iscsi-target-01'

@description('Name of the resourceGroup for the existing virtual network and disk to deploy the Disk Pool.')
param existingResourceGroupName string

@description('Name of the existing virtual network to deploy the Disk Pool into.')
param existingVnetName string

@description('Name of the existing subnet to deploy the Disk Pool into.')
param existingSubnetName string

resource vnet 'Microsoft.Network/virtualNetworks@2020-05-01' existing = {
  scope: resourceGroup(existingResourceGroupName)
  name: existingVnetName
}

resource subnet 'Microsoft.Network/virtualNetworks/subnets@2020-05-01' existing = {
  name: existingSubnetName
  parent: vnet
}
var subnetId = subnet.id

resource disk 'Microsoft.Compute/disks@2021-04-01' existing =  {
  scope: resourceGroup(existingResourceGroupName)
  name: existingManagedDiskName
}
var diskId = disk.id

resource diskPool 'Microsoft.StoragePool/diskPools@2021-08-01' = {
  name: diskPoolName
  sku: {
    name: diskPoolSku
  }
  location: diskPoolLocation
  properties: {
    availabilityZones: [
      diskPoolAvailabilityZone
    ]
    subnetId: subnetId
    disks: [
      {
        id: diskId
      }
    ]
  }
}

resource target 'Microsoft.StoragePool/diskPools/iscsiTargets@2021-08-01' = {
  parent: diskPool
  name: targetName
  properties: {
    targetIqn: 'iqn.2021-04.org.microsoft.com:target'
    aclMode: 'Dynamic'
    luns: [
      {
        managedDiskAzureResourceId: diskId
        name: 'lun0'
      }
    ]
  }
}

@description('Location for the resources.')
param location string = resourceGroup().location

@description('Stream Analytics Job Name, can contain alphanumeric characters and hypen and must be 3-63 characters long')
@minLength(3)
@maxLength(63)
param streamAnalyticsJobName string

@description('You can choose the number of Streaming Units, ranging from 3, 7, 10, 20, 30, in multiples of 10, and continuing up to 660.')
@minValue(3)
@maxValue(660)

param numberOfStreamingUnits int

resource streamingJob 'Microsoft.StreamAnalytics/streamingjobs@2021-10-01-preview' = {
  name: streamAnalyticsJobName
  location: location
  properties: {
    sku: {
      name: 'StandardV2'
    }
    outputErrorPolicy: 'Stop'
    eventsOutOfOrderPolicy: 'Adjust'
    eventsOutOfOrderMaxDelayInSeconds: 0
    eventsLateArrivalMaxDelayInSeconds: 5
    dataLocale: 'en-US'
    transformation: {
      name: 'Transformation'
      properties: {
        streamingUnits: numberOfStreamingUnits
        query: 'SELECT
    *
INTO
    [YourOutputAlias]
FROM
    [YourInputAlias]'
      }
    }
  }
}

output location string = location
output name string = streamingJob.name
output resourceGroupName string = resourceGroup().name
output resourceId string = streamingJob.id

